// ===== Automatik: welches Quiz ist gerade aktiv? =====
// Ein Quiz startet an seinem Datum um 06:00 Uhr deutscher Zeit (Europe/Berlin).
// Aktiv ist das Quiz mit dem neuesten erreichten Datum, das schon Fragen hat.
// Fehlen für die aktuelle Woche noch Fragen, bleibt das letzte fertige Quiz aktiv.
export const START_STUNDE = 6;
const pad = (n) => String(n).padStart(2, "0");

// Minuten, um die die deutsche Uhr der UTC-Zeit voraus ist (60 im Winter, 120 im Sommer)
function berlinVersatz(zeit) {
  try {
    const t = Object.fromEntries(new Intl.DateTimeFormat("en-US", {
      timeZone: "Europe/Berlin", hourCycle: "h23",
      year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit"
    }).formatToParts(zeit).map(p => [p.type, p.value]));
    return Math.round((Date.UTC(+t.year, +t.month - 1, +t.day, +t.hour, +t.minute) - Math.floor(zeit.getTime() / 60000) * 60000) / 60000);
  } catch (e) {
    return 60;
  }
}

// Startzeitpunkt eines Wochen-Quiz als Date (Datum 06:00 Uhr deutscher Zeit)
export function startZeit(w) {
  const [y, m, d] = w.datum.split("-").map(Number);
  const utc = Date.UTC(y, m - 1, d, START_STUNDE);
  return new Date(utc - berlinVersatz(new Date(utc)) * 60000);
}

const nachDatum = (wochen) => [...wochen].sort((a, b) => a.datum.localeCompare(b.datum) || a.nr - b.nr);

// Das automatisch aktive Quiz zum Zeitpunkt „jetzt“ (oder null, wenn noch keins gestartet ist)
export function aktivesQuiz(jetzt = new Date(), wochen = WOCHEN) {
  return nachDatum(wochen).filter(w => w.fragen.length && startZeit(w) <= jetzt).pop() || null;
}

// Das nächste Quiz mit Fragen, das automatisch startet (oder null)
export function naechstesQuiz(jetzt = new Date(), wochen = WOCHEN) {
  return nachDatum(wochen).find(w => w.fragen.length && startZeit(w) > jetzt) || null;
}

// Der nächste geplante Termin – auch wenn dafür noch Fragen fehlen (oder null)
export function naechsterTermin(jetzt = new Date(), wochen = WOCHEN) {
  return nachDatum(wochen).find(w => startZeit(w) > jetzt) || null;
}

// Ranking-Runde eines Wochen-Quiz, z. B. „Q01-2026-10-09“
export function rundeFuer(w) {
  return `Q${pad(w.nr)}-${w.datum}`;
}

// Gesamtstand aus config/current: { mode, week, round }
// mode "auto" (Standard) = nach Datum, "manual" = von Hand gesetztes Quiz (set/round)
export function freitagsStand(cfg = {}, jetzt = new Date(), wochen = WOCHEN) {
  if (cfg.mode === "manual") {
    const week = wochen.find(w => w.nr === cfg.set && w.fragen.length) || null;
    return { mode: "manual", week, round: cfg.round || "start" };
  }
  const week = aktivesQuiz(jetzt, wochen);
  return { mode: "auto", week, round: week ? rundeFuer(week) : (cfg.round || "start") };
}

// „Fr., 09.10.2026, 06:00 Uhr“
export function startText(w) {
  const d = new Date(w.datum + "T12:00:00").toLocaleDateString("de-DE", { weekday: "short", day: "2-digit", month: "2-digit", year: "numeric" });
  return `${d}, ${pad(START_STUNDE)}:00 Uhr`;
}
